```js
// Input files:
// constants.js
export const API_URL = 'https://api.example.com';

// main.js
import { API_URL } from './constants.js';
console.log(API_URL);

// With inlineConst: true, the bundled output becomes:
console.log('https://api.example.com');

// Instead of:
const API_URL = 'https://api.example.com';
console.log(API_URL);
```

